import json

with open('inventory.json') as f:
    inv = json.load(f)
if not isinstance(inv, dict):
    inv = {}
inv = {str(k): int(v) for k, v in inv.items()}

rejected = []
with open('transactions.txt') as f:
    lines = f.read().split('\n')

for lineno, raw in enumerate(lines, 1):
    line = raw.strip()
    if not line:
        continue
    parts = line.split()
    if len(parts) != 3:
        rejected.append(lineno)
        continue
    op, sku, qty_s = parts[0], parts[1], parts[2]
    try:
        qty = int(qty_s)
    except ValueError:
        rejected.append(lineno)
        continue
    if op == 'add':
        inv[sku] = inv.get(sku, 0) + qty
    elif op == 'remove':
        if sku not in inv or inv[sku] - qty < 0:
            rejected.append(lineno)
        else:
            inv[sku] -= qty
    else:
        rejected.append(lineno)

with open('inventory_after.json', 'w') as f:
    json.dump(inv, f, indent=2)
    f.write('\n')

with open('rejected.txt', 'w') as f:
    for n in rejected:
        f.write(str(n) + '\n')

print(json.dumps(inv, indent=2))
print('REJECTED:', rejected)
